def ref(inp):
    lines = [l for l in inp.split("\n") if l.strip() != ""]
    nums = json.loads(lines[0])
    k = json.loads(lines[1])
    # Choose a common target integer x; element i can be made equal to x
    # iff |nums[i] - x| <= k. Non-chosen elements are irrelevant, so the
    # answer is the maximum over all integer targets x of the number of
    # elements that can reach x.
    lo = min(nums) - k - 1
    hi = max(nums) + k + 1
    best = 0
    for x in range(lo, hi + 1):
        cnt = sum(1 for a in nums if abs(a - x) <= k)
        if cnt > best:
            best = cnt
    return json.dumps(best)
