import json
from hypothesis import strategies as st

@st.composite
def gen(draw):
    n = draw(st.integers(1, 8))
    nums = draw(st.lists(st.integers(0, 12), min_size=n, max_size=n))
    k = draw(st.integers(0, 6))
    if draw(st.booleans()):
        # edge case: all-equal elements
        v = draw(st.integers(0, 12))
        nums = [v] * n
    return f"{json.dumps(nums)}\n{k}"

def validate(inp):
    lines = inp.split("\n")
    if len(lines) != 2:
        return False
    try:
        nums = json.loads(lines[0])
        k = json.loads(lines[1])
    except Exception:
        return False
    if not isinstance(nums, list) or not isinstance(k, int) or isinstance(k, bool):
        return False
    if not (1 <= len(nums) <= 10**5):
        return False
    if not all(isinstance(x, int) and not isinstance(x, bool) and 0 <= x <= 10**5 for x in nums):
        return False
    if not (0 <= k <= 10**5):
        return False
    return True

def ref(inp):
    lines = inp.split("\n")
    nums = json.loads(lines[0])
    k = json.loads(lines[1])
    # Each index i can end up at any value in [nums[i]-k, nums[i]+k] (each used once).
    # The beauty is the max over target values x of the number of indices whose
    # interval contains x (unchanged elements equal to x are covered as well).
    best = 0
    for x in range(0, max(nums) + k + 1):
        cnt = sum(1 for v in nums if abs(v - x) <= k)
        best = max(best, cnt)
    return json.dumps(best)
